control_files../postinst:
#!/bin/bash

#set -e;

function install_init {
  chmod +x "/opt/wemeet/wemeetapp.sh";
  chmod +x "/opt/wemeet/bin/wemeetapp";
}

function update_desktop {
  update-desktop-database -q;
}

function install_icons {
  wemeet_icon_dir=/opt/wemeet/icons
  wemeet_icon_theme=hicolor

  for i in 16 32 64 128 256; do
    png_file="${wemeet_icon_dir}/${wemeet_icon_theme}/${i}x${i}/mimetypes/wemeetapp.png"
    if [ -e ${png_file} ] ; then
      xdg-icon-resource install --context mimetypes --mode system --size ${i} ${png_file} wemeetapp
    fi
  done
}

function kill_wemeetapp {
  PROC_NAME=wemeetapp
  pkill -f $PROC_NAME
}

install_init;
install_icons;
update_desktop;
kill_wemeetapp;

exit 0;

control_files../postrm:
#!/bin/bash

#set -e;

function remove_wemeet_appdata {
  find /home/* -maxdepth 3 -name wemeetapp -type d -exec rm -rf {} \;;
}

function remove_wemeet_icons {
  find /usr/share/icons/hicolor/* -maxdepth 3 -name '*wemeetapp*' -type f -exec rm -rf {} \;;
}

function update_desktop {
  update-desktop-database -q;
}

#remove_wemeet_appdata;
remove_wemeet_icons;
update_desktop;

exit 0;

